//! Replays the workspace's share of the oracle corpus: every case of a kind
//! this crate answers must get the answer upstream's TypeScript gave, compared
//! as text. The corpus is regenerated by `tools/oracle/refresh.sh`; nothing
//! here needs upstream or Bun.

use std::fs;
use std::path::Path;

use focus_js::json::stringify;
use focus_workspace::oracle::{KINDS, run_case};
use serde_json::{Value, json};

#[test]
fn every_record_resolution_gets_upstreams_answer() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/oracle");
    let cases = fs::read_to_string(dir.join("cases.ndjson")).unwrap();
    let expected = fs::read_to_string(dir.join("expected.ndjson")).unwrap();
    let cases: Vec<&str> = cases.lines().filter(|l| !l.is_empty()).collect();
    let expected: Vec<&str> = expected.lines().filter(|l| !l.is_empty()).collect();
    assert_eq!(
        cases.len(),
        expected.len(),
        "cases.ndjson and expected.ndjson are out of step"
    );

    let mut replayed = 0;
    let mut outcomes = std::collections::BTreeMap::new();
    let mut differing = Vec::new();
    for (line, want) in cases.iter().zip(&expected) {
        // Parsed as upstream's driver parses it, so nested objects are in the
        // order a JS object enumerates them.
        let case: Value = focus_js::json::parse(line).unwrap();
        if !KINDS.contains(&case["kind"].as_str().unwrap_or_default()) {
            continue;
        }
        replayed += 1;
        let answer = run_case(&case);
        let outcome = match (
            answer.get("error"),
            answer.get("intent"),
            answer.get("binding"),
        ) {
            (Some(Value::String(error)), _, _) if error == "<runtime>" => "unreadable registry",
            (Some(_), _, _) => "refused selector",
            (_, _, Some(Value::Object(_))) => "bound session",
            (_, Some(Value::String(_)), _) => "intent",
            _ => "space only",
        };
        *outcomes.entry(outcome).or_insert(0) += 1;
        let got = stringify(&json!({ "id": case["id"], "out": answer }));
        if got != *want {
            differing.push(format!(
                "{}\n  upstream: {want}\n  focus:    {got}",
                case["id"]
            ));
        }
    }
    assert!(replayed >= 300, "too few selection cases: {replayed}");
    // A corpus where nothing resolves, or everything does, would prove little.
    for outcome in [
        "intent",
        "space only",
        "bound session",
        "refused selector",
        "unreadable registry",
    ] {
        assert!(
            outcomes.get(outcome).copied().unwrap_or(0) >= 10,
            "too few `{outcome}` cases: {outcomes:?}"
        );
    }
    assert!(
        differing.is_empty(),
        "{} selection cases differ from upstream; first:\n{}",
        differing.len(),
        differing
            .iter()
            .take(3)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}
